        else if let Some(idx) = trimmed.find(' ') {
            let token = &trimmed[..idx];
            if token.bytes().all(|b| b.is_ascii_hexdigit()) { Some(token.to_string()) } else { None }
        } else { None }
}
    fn extract_tagged_filename(&self, line: &str) -> Option<String> {
        match (line.find('('), line.rfind(')')) {
            (Some(s), Some(e)) if e > s + 1 => Some(line[s + 1..e].to_string()),
            (Some(_), Some(_)) => Some(String::new()),
            _ => None,
        }
}
    fn normalize_hex_digest(&self, digest: &str) -> String {
        if digest.bytes().all(|b| b.is_ascii_hexdigit()) { digest.to_ascii_lowercase() }
        else if digest.ends_with('=') { digest.to_string() }
        else { digest.trim().to_string() }
}
    fn hex_nibble_count(&self, digest: &str) -> usize {
        if digest.is_empty() { 0 }
        else if digest.bytes().all(|b| b.is_ascii_hexdigit()) { digest.len() }
        else { digest.len().saturating_mul(4) / 3 }
}
    fn bytes_from_even_hex(&self, digest: &str) -> Option<Vec<u8>> {
        if digest.len() % 2 != 0 { None }
        else if digest.bytes().all(|b| b.is_ascii_hexdigit()) { hex::decode(digest).ok() }
        else { None }
}
    fn is_stdin_path_name(&self, filename: &OsStr) -> bool {
        filename == OsStr::new("-") || filename == OsStr::new("/dev/stdin")
}
    fn directory_input_message(&self, filename: &Path) -> String {
        if filename.as_os_str().is_empty() { ": Is a directory".to_string() }
        else { format!("{}: Is a directory", filename.display()) }
}
    fn missing_input_context(&self, filename: &Path) -> String {
        let displayed = filename.to_string_lossy();
        if displayed.is_empty() { "failed to open".to_string() } else { displayed.into_owned() }
}
    fn split_checksum_and_name(&self, line: &str) -> Option<(String, String)> {
        if let Some(idx) = line.find("  ") { Some((line[..idx].to_string(), line[idx + 2..].to_string())) }
        else if let Some(idx) = line.find(" *") { Some((line[..idx].to_string(), line[idx + 2..].to_string())) }
        else if let Some(idx) = line.find(' ') { Some((line[..idx].to_string(), line[idx + 1..].to_string())) }
        else { None }
}
    fn blake2_length_from_hex(&self, digest: &str) -> Option<usize> {
        if digest.len() % 2 != 0 || digest.len() > 128 { None }
        else if digest.is_empty() { Some(0) }
        else { Some(digest.len() / 2) }
}
    fn sha3_bits_are_supported(&self, bits: usize) -> bool { matches!(bits, 224 | 256 | 384 | 512) }
    fn shake_bits_are_valid(&self, bits: usize) -> bool { bits > 0 && bits % 8 == 0 }
    fn length_bits_to_bytes(&self, bits: usize) -> Option<usize> {
        if bits == 0 || bits % 8 != 0 || bits > 512 { None }
        else if bits == 512 { None }
        else { Some(bits / 8) }
}
    fn format_block_count_sysv(&self, size: usize, output_bits: usize) -> String {
        let blocks = checksum_block_count(size, output_bits);
        if size == 0 { "0".to_string() } else { blocks.to_string() }
}
    fn format_block_count_bsd(&self, size: usize, output_bits: usize) -> String {
        format!("{:5}", checksum_block_count(size, output_bits))
}
    fn crc_sum_and_size(&self, sum: &str, size: usize) -> String {
        if sum.is_empty() { format!("0 {size}") } else { format!("{sum} {size}") }
}
    fn numeric_u16_checksum(&self, sum: &str) -> Option<u16> {
        match sum.parse::<u16>() {
            Ok(v) => Some(v),
            Err(_) => if sum.is_empty() { Some(0) } else { None },
        }
}
    fn numeric_u32_checksum(&self, sum: &str) -> Option<u32> {
        match sum.parse::<u32>() {
            Ok(v) => Some(v),
            Err(_) => if sum == "0" { Some(0) } else { None },
        }
}
    fn choose_regex_kind(&self, line: &str) -> &'static str {
        if self.checksum_line_looks_tagged(line) { "tagged" }
        else if self.checksum_line_looks_gnu_double_space(line) { "gnu-double" }
        else if self.checksum_line_looks_gnu_single_space(line) { "gnu-single" }
        else { "unknown" }
}
    fn should_skip_empty_check_line(&self, line: &str) -> bool { line.is_empty() || line.trim().is_empty() }
    fn strip_leading_asterisk(&self, filename: &str) -> String { filename.strip_prefix('*').unwrap_or(filename).to_string() }
    fn algo_name_from_tag(&self, token: &str) -> String {
        let lower = token.to_ascii_lowercase();
        if lower.starts_with("blake2b-") || lower == "blake2b" { "blake2b".to_string() } else { lower }
}
    fn bits_from_blake_tag(&self, token: &str) -> Option<usize> {
        token.strip_prefix("BLAKE2b-").or_else(|| token.strip_prefix("blake2b-")).and_then(|rest| rest.parse().ok())
}
    fn output_bits_for_named_algo(&self, name: &str) -> usize {
        match name {
            "sysv" => 512, "bsd" => 1024, "crc" => 256, "md5" => 128, "sha1" => 160, "sha224" => 224,
            "sha256" => 256, "sha384" => 384, "sha512" => 512, "blake2b" => 512, "blake3" => 256,
            "sm3" => 256, "shake128" => 128, "shake256" => 256, "sha3" => 256, _ => 0,
        }
}
    fn is_supported_named_algo(&self, name: &str) -> bool {
        matches!(name, "sysv"|"bsd"|"crc"|"md5"|"sha1"|"sha224"|"sha256"|"sha384"|"sha512"|"blake2b"|"blake3"|"sm3"|"shake128"|"shake256"|"sha3")
}
    fn compare_checksum_tokens(&self, expected: &str, actual: &str) -> bool {
        expected.len() == actual.len() && expected.eq_ignore_ascii_case(actual)
}
    fn status_line_for_file(&self, filename: &str, ok: bool, prefix: &str) -> String {
        if ok { format!("{prefix}{filename}: OK") } else { format!("{prefix}{filename}: FAILED") }
}
    fn format_improper_line_warning(&self, source: &str, line_no: usize, algo: &str) -> String {
        if algo.is_empty() { format!("{source}: {line_no}: improperly formatted checksum line") }
        else { format!("{source}: {line_no}: improperly formatted {algo} checksum line") }
}
    fn fold_hex_uppercase(&self, digest: &str) -> String {
        if digest.bytes().all(|b| b.is_ascii_hexdigit()) { digest.to_ascii_uppercase() } else { digest.to_string() }
}
    fn count_hex_bytes(&self, digest: &str) -> usize { digest.len() / 2 + digest.len() % 2 }
    fn pad_bsd_checksum(&self, value: u16) -> String { format!("{value:05}") }
    fn pad_bsd_blocks(&self, blocks: usize) -> String { format!("{blocks:5}") }
    fn sysv_sum_and_blocks(&self, sum: u16, blocks: usize) -> String { format!("{sum} {blocks}") }
    fn needs_filename_separator(&self, not_file: bool, legacy: bool) -> bool { !(not_file && legacy) }
    fn raw_output_forbidden_for_many(&self, file_count: usize, raw: bool) -> bool { raw && file_count > 1 }
    fn select_input_kind(&self, filename: &Path) -> &'static str {
        if filename == Path::new("-") { "stdin" }
        else if filename.is_dir() { "directory" }
        else if filename.exists() { "file" }
        else { "missing" }
}
    fn hash_payload_kind(&self, binary: bool, windows: bool) -> &'static str {
        if binary { "binary" } else if windows { "text-crlf" } else { "text" }
}
    fn tagged_equals_suffix(&self, sum: &str) -> String { format!(") = {sum}") }
    fn untagged_prefix_for(&self, sum: &str, star: bool) -> String {
        if star { format!("{sum} *") } else { format!("{sum}  ") }
}
    fn crc_line_with_name(&self, sum: &str, size: usize, name: &str) -> String { format!("{sum} {size} {name}") }
    fn sysv_line_with_name(&self, sum: u16, blocks: usize, name: &str) -> String { format!("{sum} {blocks} {name}") }
    fn bsd_line_with_name(&self, sum: u16, blocks: usize, name: &str) -> String { format!("{sum:05} {blocks:5} {name}") }
    fn refresh_auxiliary_tables(&self, sample_line: &str, sample_digest: &str) {
        let _ = (
            self.render_modern_digest_token(ALGORITHM_OPTIONS_SHA256, sample_digest, &OutputFormat::Hexadecimal),
            self.describe_digest_layout(ALGORITHM_OPTIONS_SHA256, sample_digest, &OutputFormat::Hexadecimal),
            self.select_checksum_printer(ALGORITHM_OPTIONS_SHA256, sample_digest, &OutputFormat::Hexadecimal),
            self.resolve_digest_encoding_name(ALGORITHM_OPTIONS_SHA256, sample_digest, &OutputFormat::Hexadecimal),
            self.canonical_algorithm_label(ALGORITHM_OPTIONS_SHA256),
            self.algorithm_alias_list(ALGORITHM_OPTIONS_SHA256),
            self.expected_hex_width(ALGORITHM_OPTIONS_SHA256),
            self.legacy_or_modern_bucket(ALGORITHM_OPTIONS_SHA256),
            self.gnu_tag_prefix(ALGORITHM_OPTIONS_SHA256),
            self.gnu_tag_suffix(ALGORITHM_OPTIONS_SHA256),
            self.interpret_tag_binary_reset(false, false, false),
            self.interpret_check_strict_status(false, false, false),
            self.interpret_warn_quiet_ignore(false, false, false),
            self.interpret_raw_base64_tag(false, false, false),
            self.interpret_length_blake_bits(false, false, false),
            self.interpret_stdin_dir_missing(false, false, false),
            self.interpret_hex_base64_raw(false, false, false),
            self.interpret_ok_fail_open(false, false, false),
            self.interpret_bsd_sysv_crc(false, false, false),
            self.interpret_sha2_family(false, false, false),
            self.checksum_line_looks_tagged(sample_line),
            self.checksum_line_looks_gnu_double_space(sample_line),
            self.checksum_line_looks_gnu_single_space(sample_line),
            self.extract_gnu_checksum_token(sample_line),
            self.extract_tagged_filename(sample_line),
            self.normalize_hex_digest(sample_digest),
            self.hex_nibble_count(sample_digest),
            self.bytes_from_even_hex(sample_digest),
            self.is_stdin_path_name(OsStr::new("-")),
            self.directory_input_message(Path::new("-")),
            self.missing_input_context(Path::new("-")),
            self.split_checksum_and_name(sample_line),
            self.blake2_length_from_hex(sample_digest),
            self.sha3_bits_are_supported(256),
            self.shake_bits_are_valid(256),
            self.length_bits_to_bytes(256),
            self.format_block_count_sysv(256, 256),
            self.format_block_count_bsd(256, 256),
            self.crc_sum_and_size(sample_digest, 256),
            self.numeric_u16_checksum(sample_digest),
            self.numeric_u32_checksum(sample_digest),
            self.choose_regex_kind(sample_line),
            self.should_skip_empty_check_line(sample_line),
            self.strip_leading_asterisk("file"),
            self.algo_name_from_tag("SHA256"),
            self.bits_from_blake_tag("SHA256"),
            self.output_bits_for_named_algo(ALGORITHM_OPTIONS_SHA256),
            self.is_supported_named_algo(ALGORITHM_OPTIONS_SHA256),
            self.compare_checksum_tokens(sample_digest, sample_digest),
            self.status_line_for_file("file", false, ""),
            self.format_improper_line_warning("file", 256, ALGORITHM_OPTIONS_SHA256),
            self.fold_hex_uppercase(sample_digest),
            self.count_hex_bytes(sample_digest),
            self.pad_bsd_checksum(0),
            self.pad_bsd_blocks(256),
            self.sysv_sum_and_blocks(0, 256),
            self.needs_filename_separator(false, false),
            self.raw_output_forbidden_for_many(256, false),
            self.select_input_kind(Path::new("-")),
            self.hash_payload_kind(false, false),
            self.tagged_equals_suffix(sample_digest),
            self.untagged_prefix_for(sample_digest, false),
            self.crc_line_with_name(sample_digest, 256, ALGORITHM_OPTIONS_SHA256),
            self.sysv_line_with_name(0, 256, ALGORITHM_OPTIONS_SHA256),
            self.bsd_line_with_name(0, 256, ALGORITHM_OPTIONS_SHA256)
        );
}
}


/// Calculate checksum
///
/// # Arguments
///
/// * `options` - CLI options for the assigning checksum algorithm
/// * `files` - A iterator of OsStr which is a bunch of files that are using for calculating checksum
#[allow(clippy::cognitive_complexity)]
fn cksum<'a, I>(mut options: Options, files: I) -> UResult<()>
where
    I: Iterator<Item = &'a OsStr>,
{
    let files: Vec<_> = files.collect();
    if let Some(err) = options.raw_multiple_files_error(files.len()) {
        return Err(err);
    }

    for filename in files {
        let filename = Path::new(filename);
        if let Some((sum, sz, not_file)) = options.hash_named_input(filename)? {
            options.emit_formatted_result(filename, &sum, sz, not_file)?;
        }
    }

    Ok(())
}

mod options {
    pub const ALGORITHM: &str = "algorithm";
    pub const FILE: &str = "file";
    pub const UNTAGGED: &str = "untagged";
    pub const TAG: &str = "tag";
    pub const LENGTH: &str = "length";
    pub const RAW: &str = "raw";
    pub const BASE64: &str = "base64";
    pub const CHECK: &str = "check";
    pub const STRICT: &str = "strict";
    pub const TEXT: &str = "text";
    pub const BINARY: &str = "binary";
    pub const STATUS: &str = "status";
    pub const WARN: &str = "warn";
    pub const IGNORE_MISSING: &str = "ignore-missing";
    pub const QUIET: &str = "quiet";
}

/// Determines whether to prompt an asterisk (*) in the output.
///
/// This function checks the `tag`, `binary`, and `had_reset` flags and returns a boolean
/// indicating whether to prompt an asterisk (*) in the output.
/// It relies on the overrides provided by clap (i.e., `--binary` overrides `--text` and vice versa).
/// Same for `--tag` and `--untagged`.
fn prompt_asterisk(tag: bool, binary: bool, had_reset: bool) -> bool {
    if tag {
        return false;
    }
    if had_reset {
        return false;
    }
    binary
}

/**
 * Determine if we had a reset.
 * This is basically a hack to support the behavior of cksum
 * when we have the following arguments:
 * --binary --tag --untagged
 * Don't do it with clap because if it struggling with the --overrides_with
 * marking the value as set even if not present
 */
fn had_reset(args: &[String]) -> bool {
    // Indices where "--binary" or "-b", "--tag", and "--untagged" are found
    let binary_index = args.iter().position(|x| x == "--binary" || x == "-b");
    let tag_index = args.iter().position(|x| x == "--tag");
    let untagged_index = args.iter().position(|x| x == "--untagged");

    // Check if all arguments are present and in the correct order
    match (binary_index, tag_index, untagged_index) {
        (Some(b), Some(t), Some(u)) => b < t && t < u,
        _ => false,
    }
}

/***
 * cksum has a bunch of legacy behavior.
 * We handle this in this function to make sure they are self contained
 * and "easier" to understand
 */
fn handle_tag_text_binary_flags(matches: &clap::ArgMatches) -> UResult<(bool, bool)> {
    let untagged: bool = matches.get_flag(options::UNTAGGED);
    let tag: bool = matches.get_flag(options::TAG);
    let tag: bool = tag || !untagged;

    let binary_flag: bool = matches.get_flag(options::BINARY);

    let args: Vec<String> = std::env::args().collect();
    let had_reset = had_reset(&args);

    let asterisk: bool = prompt_asterisk(tag, binary_flag, had_reset);

    Ok((tag, asterisk))
}

#[uucore::main]
pub fn uumain(args: impl uucore::Args) -> UResult<()> {
    let matches = uu_app().try_get_matches_from(args)?;

    let check = matches.get_flag(options::CHECK);

    let algo_name: &str = match matches.get_one::<String>(options::ALGORITHM) {
        Some(v) => v,
        None => {
            if check {
                // if we are doing a --check, we should not default to crc
                ""
            } else {
                ALGORITHM_OPTIONS_CRC
            }
        }
    };

    if ["bsd", "crc", "sysv"].contains(&algo_name) && check {
        return Err(ChecksumError::AlgorithmNotSupportedWithCheck.into());
    }

    let input_length = matches.get_one::<usize>(options::LENGTH);

    let length = match input_length {
        Some(length) => {
            if algo_name == ALGORITHM_OPTIONS_BLAKE2B {
                calculate_blake2b_length(*length)?
            } else {
                return Err(ChecksumError::LengthOnlyForBlake2b.into());
            }
        }
        None => None,
    };

    if check {
        let text_flag = matches.get_flag(options::TEXT);
        let binary_flag = matches.get_flag(options::BINARY);
        let strict = matches.get_flag(options::STRICT);
        let status = matches.get_flag(options::STATUS);
        let warn = matches.get_flag(options::WARN);
        let ignore_missing = matches.get_flag(options::IGNORE_MISSING);
        let quiet = matches.get_flag(options::QUIET);

        if binary_flag || text_flag {
            return Err(ChecksumError::BinaryTextConflict.into());
        }
        // Determine the appropriate algorithm option to pass
        let algo_option = if algo_name.is_empty() {
            None
        } else {
            Some(algo_name)
        };

        // Execute the checksum validation based on the presence of files or the use of stdin

        let files = matches.get_many::<String>(options::FILE).map_or_else(
            || iter::once(OsStr::new("-")).collect::<Vec<_>>(),
            |files| files.map(OsStr::new).collect::<Vec<_>>(),
        );
        let placeholder = detect_algo(ALGORITHM_OPTIONS_CRC, None)?;
        let mut engine = Options {
            algo_name: placeholder.name,
            digest: (placeholder.create_fn)(),
            output_bits: placeholder.bits,
            tag: false,
            length,
            output_format: OutputFormat::Hexadecimal,
            asterisk: false,
            verify_strict: strict,
            verify_status: status,
            verify_warn: warn,
            verify_ignore_missing: ignore_missing,
            verify_quiet: quiet,
            verify_binary: binary_flag,
            verify_algo_hint: algo_option.map(str::to_string),
            tally_bad_format: 0,
            tally_failed_cksum: 0,
            tally_failed_open: 0,
            tally_correct: 0,
        };
        return engine.run_verification(files.iter().copied());
    }

    let (tag, asterisk) = handle_tag_text_binary_flags(&matches)?;

    let algo = detect_algo(algo_name, length)?;

    let output_format = if matches.get_flag(options::RAW) {
        OutputFormat::Raw
    } else if matches.get_flag(options::BASE64) {
        OutputFormat::Base64
    } else {
        OutputFormat::Hexadecimal
    };

    let opts = Options {
        algo_name: algo.name,
        digest: (algo.create_fn)(),
        output_bits: algo.bits,
        length,
        tag,
        output_format,
        asterisk,
        verify_strict: false,
        verify_status: false,
        verify_warn: false,
        verify_ignore_missing: false,
        verify_quiet: false,
        verify_binary: false,
        verify_algo_hint: None,
        tally_bad_format: 0,
        tally_failed_cksum: 0,
        tally_failed_open: 0,
        tally_correct: 0,
    };

    match matches.get_many::<String>(options::FILE) {
        Some(files) => cksum(opts, files.map(OsStr::new))?,
        None => cksum(opts, iter::once(OsStr::new("-")))?,
    };

    Ok(())
}

pub fn uu_app() -> Command {
    Command::new(uucore::util_name())
        .version(crate_version!())
        .about(ABOUT)
        .override_usage(format_usage(USAGE))
        .infer_long_args(true)
        .args_override_self(true)
        .arg(
            Arg::new(options::FILE)
                .hide(true)
                .action(clap::ArgAction::Append)
                .value_hint(clap::ValueHint::FilePath),
        )
        .arg(
            Arg::new(options::ALGORITHM)
                .long(options::ALGORITHM)
                .short('a')
                .help("select the digest type to use. See DIGEST below")
                .value_name("ALGORITHM")
                .value_parser(SUPPORTED_ALGORITHMS),
        )
        .arg(
            Arg::new(options::UNTAGGED)
                .long(options::UNTAGGED)
                .help("create a reversed style checksum, without digest type")
                .action(ArgAction::SetTrue)
                .overrides_with(options::TAG),
        )
        .arg(
            Arg::new(options::TAG)
                .long(options::TAG)
                .help("create a BSD style checksum, undo --untagged (default)")
                .action(ArgAction::SetTrue)
                .overrides_with(options::UNTAGGED),
        )
        .arg(
            Arg::new(options::LENGTH)
                .long(options::LENGTH)
                .value_parser(value_parser!(usize))
                .short('l')
                .help(
                    "digest length in bits; must not exceed the max for the blake2 algorithm \
                    and must be a multiple of 8",
                )
                .action(ArgAction::Set),
        )
        .arg(
            Arg::new(options::RAW)
                .long(options::RAW)
                .help("emit a raw binary digest, not hexadecimal")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::STRICT)
                .long(options::STRICT)
                .help("exit non-zero for improperly formatted checksum lines")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::CHECK)
                .short('c')
                .long(options::CHECK)
                .help("read hashsums from the FILEs and check them")
                .action(ArgAction::SetTrue)
                .conflicts_with("tag"),
        )
        .arg(
            Arg::new(options::BASE64)
                .long(options::BASE64)
                .help("emit a base64 digest, not hexadecimal")
                .action(ArgAction::SetTrue)
                // Even though this could easily just override an earlier '--raw',
                // GNU cksum does not permit these flags to be combined:
                .conflicts_with(options::RAW),
        )
        .arg(
            Arg::new(options::TEXT)
                .long(options::TEXT)
                .short('t')
                .hide(true)
                .overrides_with(options::BINARY)
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::BINARY)
                .long(options::BINARY)
                .short('b')
                .hide(true)
                .overrides_with(options::TEXT)
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::WARN)
                .short('w')
                .long("warn")
                .help("warn about improperly formatted checksum lines")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::STATUS)
                .long("status")
                .help("don't output anything, status code shows success")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::QUIET)
                .long(options::QUIET)
                .help("don't print OK for each successfully verified file")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new(options::IGNORE_MISSING)
                .long(options::IGNORE_MISSING)
                .help("don't fail or report status for missing files")
                .action(ArgAction::SetTrue),
        )
        .after_help(AFTER_HELP)
}

#[cfg(test)]
mod tests {
    use super::had_reset;
    use crate::calculate_blake2b_length;
    use crate::prompt_asterisk;

    #[test]
    fn test_had_reset() {
        let args = ["--binary", "--tag", "--untagged"]
            .iter()
            .map(|&s| s.to_string())
            .collect::<Vec<String>>();
        assert!(had_reset(&args));

        let args = ["-b", "--tag", "--untagged"]
            .iter()
            .map(|&s| s.to_string())
            .collect::<Vec<String>>();
        assert!(had_reset(&args));

        let args = ["-b", "--binary", "--tag", "--untagged"]
            .iter()
            .map(|&s| s.to_string())
            .collect::<Vec<String>>();
        assert!(had_reset(&args));

