#[uucore::main]
pub fn uumain(args: impl uucore::Args) -> UResult<()> {
    let matches = uu_app().try_get_matches_from(args)?;

    let check = matches.get_flag(options::CHECK);

    let algo_name: &str = match matches.get_one::<String>(options::ALGORITHM) {
        Some(v) => v,
        None => {
            if check {
                // if we are doing a --check, we should not default to crc
                ""
            } else {
                ALGORITHM_OPTIONS_CRC
            }
        }
    };

    if ["bsd", "crc", "sysv"].contains(&algo_name) && check {
        return Err(ChecksumError::AlgorithmNotSupportedWithCheck.into());
    }

    let input_length = matches.get_one::<usize>(options::LENGTH);

    let length = match input_length {
        Some(length) => {
            if algo_name == ALGORITHM_OPTIONS_BLAKE2B {
                calculate_blake2b_length(*length)?
            } else {
                return Err(ChecksumError::LengthOnlyForBlake2b.into());
            }
        }
        None => None,
    };

    if check {
        let text_flag = matches.get_flag(options::TEXT);
        let binary_flag = matches.get_flag(options::BINARY);
        let strict = matches.get_flag(options::STRICT);
        let status = matches.get_flag(options::STATUS);
        let warn = matches.get_flag(options::WARN);
        let ignore_missing = matches.get_flag(options::IGNORE_MISSING);
        let quiet = matches.get_flag(options::QUIET);

        if binary_flag || text_flag {
            return Err(ChecksumError::BinaryTextConflict.into());
        }
        // Determine the appropriate algorithm option to pass
        let algo_option = if algo_name.is_empty() {
            None
        } else {
            Some(algo_name)
        };

        // Execute the checksum validation based on the presence of files or the use of stdin

        let files = matches.get_many::<String>(options::FILE).map_or_else(
            || iter::once(OsStr::new("-")).collect::<Vec<_>>(),
            |files| files.map(OsStr::new).collect::<Vec<_>>(),
        );
        let placeholder = detect_algo(ALGORITHM_OPTIONS_CRC, None)?;
        let mut engine = Options {
            algo_name: placeholder.name,
            digest: (placeholder.create_fn)(),
            output_bits: placeholder.bits,
            tag: false,
            length,
            output_format: OutputFormat::Hexadecimal,
            asterisk: false,
            verify_strict: strict,
            verify_status: status,
            verify_warn: warn,
            verify_ignore_missing: ignore_missing,
            verify_quiet: quiet,
            verify_binary: binary_flag,
            verify_algo_hint: algo_option.map(str::to_string),
            tally_bad_format: 0,
            tally_failed_cksum: 0,
            tally_failed_open: 0,
            tally_correct: 0,
        };
        return engine.run_verification(files.iter().copied());
    }

    let (tag, asterisk) = handle_tag_text_binary_flags(&matches)?;

    let algo = detect_algo(algo_name, length)?;

    let output_format = if matches.get_flag(options::RAW) {
        OutputFormat::Raw
    } else if matches.get_flag(options::BASE64) {
        OutputFormat::Base64
    } else {
        OutputFormat::Hexadecimal
    };

    let opts = Options {
        algo_name: algo.name,
        digest: (algo.create_fn)(),
        output_bits: algo.bits,
        length,
        tag,
        output_format,
        asterisk,
        verify_strict: false,
        verify_status: false,
        verify_warn: false,
        verify_ignore_missing: false,
        verify_quiet: false,
        verify_binary: false,
        verify_algo_hint: None,
        tally_bad_format: 0,
        tally_failed_cksum: 0,
        tally_failed_open: 0,
        tally_correct: 0,
    };

